@_bonus_functools.lru_cache(maxsize=1)
def _bonus_data():
    return _bonus_json.loads(_bonus_zlib.decompress(_bonus_base64.b85decode(_BONUS_PACKED)))

def _bonus_selected(n, k):
    import cirq
    import operator
    try:
        if isinstance(n, bool) or isinstance(k, bool):
            raise TypeError
        n, k = operator.index(n), operator.index(k)
    except TypeError:
        raise NotImplementedError('Bonus requires integer N and k') from None
    if not 2 <= n <= 15 or not 1 <= k <= n // 2:
        raise NotImplementedError('Bonus domain: 2 <= N <= 15 and 1 <= k <= N // 2')
    data = _bonus_data()[f'{n},{k}']
    if data.get('adaptive'):
        circuit, outputs = _decode_bonus_adaptive(data)
        return _normalize_bonus_controlled_paulis(circuit), outputs
    if 'circuit_json' in data:
        circuit = cirq.read_json(json_text=data['circuit_json'])
        outputs = {cirq.GridQubit(*point) for point in data['outputs']}
        return circuit, outputs
    qubits = [cirq.GridQubit(*point) for point in data['qubits']]
    moments = []
    for layer in data['moments']:
        operations = []
        for op in layer:
            if op[0] == 1:
                operations.append(cirq.CZ(qubits[op[1]], qubits[op[2]]))
            else:
                operations.append(cirq.PhasedXZGate(x_exponent=op[2], z_exponent=op[3], axis_phase_exponent=op[4])(qubits[op[1]]))
        moments.append(cirq.Moment(operations))
    return cirq.Circuit(moments), set(qubits)


def _decode_bonus_adaptive(data):
    import cirq
    import sympy
    qubits=[cirq.GridQubit(*point) for point in data['qubits']]
    moments=[]
    for layer in data['moments']:
        operations=[]
        for item in layer:
            kind=item['gate']
            params=item.get('parameters',[])
            if kind=='p':gate=cirq.PhasedXZGate(x_exponent=params[0],z_exponent=params[1],axis_phase_exponent=params[2])
            elif kind=='cz':gate=cirq.CZ
            elif kind=='x':gate=cirq.XPowGate(exponent=params[0],global_shift=params[1])
            elif kind=='z':gate=cirq.ZPowGate(exponent=params[0],global_shift=params[1])
            elif kind=='m':gate=cirq.MeasurementGate(len(item['qubits']),key=item['key'],invert_mask=tuple(item['invert']))
            else:raise ValueError('Unsupported stored gate')
            op=gate.on(*[qubits[i] for i in item['qubits']])
            conditions=[]
            for condition in item.get('conditions',[]):
                if condition[0]=='key':conditions.append(cirq.KeyCondition(cirq.MeasurementKey(condition[1]),index=condition[2]))
                elif condition[0]=='zero':conditions.append(cirq.SympyCondition(sympy.Eq(sympy.Symbol(condition[1]),0)))
                elif condition[0]=='parity':conditions.append(cirq.SympyCondition(sympy.Eq(sympy.Mod(sum(sympy.Symbol(key) for key in condition[1]),2),1)))
                else:raise ValueError('Unsupported stored condition')
            if conditions:op=op.with_classical_controls(*conditions)
            operations.append(op)
        moments.append(cirq.Moment(operations))
    return cirq.Circuit(moments),{qubits[i] for i in data['outputs']}

def _normalize_bonus_controlled_paulis(circuit):
    """Use literal native PhasedXZ gates with identical controlled matrices."""
    import cirq
    import numpy as np
    moments=[]
    for moment in circuit:
        operations=[]
        for op in moment:
            if op.classical_controls:
                raw=op.without_classical_controls()
                if raw.gate==cirq.X or raw.gate==cirq.Z:
                    replacement=cirq.PhasedXZGate(
                        x_exponent=1 if raw.gate==cirq.X else 0,
                        z_exponent=1 if raw.gate==cirq.Z else 0,
                        axis_phase_exponent=0).on(*raw.qubits)
                    if not np.array_equal(cirq.unitary(raw),cirq.unitary(replacement)):
                        raise ValueError('Native control representation changed matrix')
                    op=replacement.with_classical_controls(*op.classical_controls)
            operations.append(op)
        moments.append(cirq.Moment(operations))
    return cirq.Circuit(moments)


"""Runtime appended by build_best_file.py; this file is not a submission dependency."""

_LAST_SELECTION = {}
_RESIDUAL_LIMIT = 1e-10


def _density_single(rho, unitary, axis):
    # A two-row update avoids large BLAS thread pools for tiny native gates.
    a, b = np.take(rho, 0, axis=axis), np.take(rho, 1, axis=axis)
    return np.stack((unitary[0, 0] * a + unitary[0, 1] * b,
                     unitary[1, 0] * a + unitary[1, 1] * b), axis=axis)


def _arguments(n, k, maximum=20):
    try:
        if isinstance(n, (bool, np.bool_)) or isinstance(k, (bool, np.bool_)):
            raise TypeError
        n, k = operator.index(n), operator.index(k)
    except TypeError:
        raise NotImplementedError('Integer N and excitation count are required') from None
    if not 1 <= n <= maximum or not 0 <= k <= n:
        raise NotImplementedError('Unsupported Dicke-state dimensions')
    return n, k


@functools.lru_cache(maxsize=256)
def _decode_saved(key, index):
    data = _MAIN_TEMPLATES[key][index]
    qubits = tuple(cirq.GridQubit(*q) for q in data['qubits'])
    moments = []
    for row in data['moments']:
        operations = []
        for gate in row:
            if gate[0] == 1:
                operations.append(cirq.CZ(qubits[gate[1]], qubits[gate[2]]))
            else:
                operations.append(cirq.PhasedXZGate(x_exponent=gate[2], z_exponent=gate[3],
                                                    axis_phase_exponent=gate[4])(qubits[gate[1]]))
        moments.append(cirq.Moment(operations))
    return cirq.FrozenCircuit(moments), qubits


def _native_contract(circuit, outputs, n, cz, sq):
    """Canonicalize full CZ orientation and enforce the complete main contract."""
    outputs = set(outputs)
    device = cirq_google.Willow105.metadata
    if len(outputs) != n or not outputs <= set(sq) or not outputs <= device.qubit_set:
        raise NotImplementedError('Invalid or uncalibrated output qubits')
    if set(circuit.all_qubits()) - outputs or not 0 < len(circuit) <= 1750:
        raise NotImplementedError('Ancillary qubits or unsupported circuit depth')
    allowed = {frozenset(edge): tuple(edge) for edge in cz}
    moments = []
    for moment in circuit:
        operations = []
        for op in moment:
            if op.classical_controls or any(q not in sq for q in op.qubits):
                raise NotImplementedError('Classical controls or uncalibrated gate qubits')
            gate = op.gate
            if len(op.qubits) == 1 and isinstance(gate, cirq.PhasedXZGate):
                values = (gate.x_exponent, gate.z_exponent, gate.axis_phase_exponent)
                if not all(math.isfinite(float(x)) for x in values):
                    raise NotImplementedError('Non-finite native rotation')
                x, z, a = (math.remainder(float(x), 2.0) for x in values)
                op = cirq.PhasedXZGate(x_exponent=x, z_exponent=z,
                                      axis_phase_exponent=a)(op.qubits[0])
            elif len(op.qubits) == 2 and gate == cirq.CZ and frozenset(op.qubits) in allowed:
                op = cirq.CZ(*allowed[frozenset(op.qubits)])
            else:
                raise NotImplementedError('Only calibrated full CZ and PhasedXZ gates are returned')
            operations.append(op)
        moments.append(cirq.Moment(operations))
    result = cirq.Circuit(moments)
    try:
        cirq_google.Willow105.validate_circuit(result)
    except (ValueError, TypeError) as error:
        raise NotImplementedError('Circuit is not valid on Willow105') from error
    return result, outputs


def _state_residual(circuit, outputs, n, k):
    """Full complex128 amplitude check, including relative phase, not a fidelity shortcut."""
    state = cirq.Simulator(dtype=np.complex128).simulate(
        circuit, qubit_order=sorted(outputs)).final_state_vector
    indices = np.fromiter((sum(1 << j for j in bits)
                           for bits in itertools.combinations(range(n), k)), dtype=np.int64)
    normalization = math.sqrt(math.comb(n, k))
    overlap = state[indices].sum() / normalization
    state[indices] -= overlap / normalization
    residual = float(np.linalg.norm(state))
    if not math.isfinite(residual) or residual > _RESIDUAL_LIMIT or abs(abs(overlap)**2 - 1) > 1e-10:
        raise NotImplementedError('Noiseless Dicke amplitude check failed')
    return residual


def _expected_notebook_losses(circuit, outputs, k, cz, sq, zero, one):
    """Expected 10,000-shot denominators for every X cutoff under a Pauli/readout model.

    The finite-shot Z inverse-occupancy expectation uses its asymptotic expansion.
    These are model estimates, not measured scores from quantum hardware.
    """
    order = sorted(outputs)
    n = len(order)
    rho = native_density(circuit, order, cz, sq)
    z = _readout(np.real(np.diag(rho)), order, zero, one)
    xrho = rho.reshape((2,) * (2 * n))
    for axis in range(2 * n):
        a, b = np.take(xrho, 0, axis=axis), np.take(xrho, 1, axis=axis)
        xrho = np.stack(((a + b) / math.sqrt(2), (a - b) / math.sqrt(2)), axis=axis)
    x = _readout(np.real(np.diag(xrho.reshape(1 << n, 1 << n))), order, zero, one,
                 basis_noise=sq)
    weights = np.fromiter((i.bit_count() for i in range(1 << n)), dtype=np.int64)
    shell = z[weights == k]
    f = float(shell.sum())
    if f <= 0:
        return np.full(n, np.inf)
    m = math.comb(n, k)
    delta = max(0.0, float(m * np.sum((shell / f)**2) - 1))
    sf = 10000 * f
    inv = 1 / sf + (1 - f) / sf**2 + (1 - f) * (2 - f) / sf**3
    zloss = 10000 / m * (delta + (m - 1 - delta) * inv)
    def comb(a, b):
        return math.comb(a, b) if 0 <= b <= a else 0
    losses, xloss = [], 0.0
    for ell in range(1, n + 1):
        expected = comb(ell, ell // 2) * comb(n - ell, k - ell // 2) / m if ell % 2 == 0 else 0.0
        by_weight = np.array([sum((-1)**j * comb(w, j) * comb(n - w, ell - j)
                                  for j in range(ell + 1)) / comb(n, ell) for w in range(n + 1)])
        values = by_weight[weights]
        mean = float(x @ values)
        variance = max(0.0, float(x @ (values * values)) - mean * mean)
        xloss += ((expected - mean)**2 + variance / 10000) / (expected**2 if expected else 1)
        losses.append(zloss + xloss)
    return np.array(losses)


def _clean_calibration(cz, sq, zero, one):
    device = cirq_google.Willow105.metadata
    physical_pairs = {frozenset(p) for p in device.qubit_pairs}
    def finite_rate(value):
        try:
            return len(value) == 2 and all(math.isfinite(float(x)) for x in value) and 0 <= float(value[0]) <= 1 and float(value[1]) >= 0
        except (TypeError, ValueError):
            return False
    sq = {q: v for q, v in sq.items() if q in device.qubit_set and finite_rate(v)}
    cz = {p: v for p, v in cz.items() if len(p) == 2 and frozenset(p) in physical_pairs
          and all(q in sq for q in p) and finite_rate(v)}
    # Readout entries are part of the notebook input, not guessed calibration data.
    sq = {q: v for q, v in sq.items() if q in zero and q in one and finite_rate(zero[q]) and finite_rate(one[q])}
    cz = {p: v for p, v in cz.items() if all(q in sq for q in p)}
    return cz, sq, {q: zero[q] for q in sq}, {q: one[q] for q in sq}


def create_dicke_state(num_qubits, num_excitations, cz_pauli_error_rate,
                       sq_pauli_error_rate, zero_errors, one_errors):
    """Return a native exact Dicke circuit on the supplied Willow calibration.

    Both submitted implementations contribute independently verified templates.
    Small cases use predicted notebook denominators across all X cutoffs;
    larger cases use the supplied gate/readout calibration ranking. Unknown
    hardware noise cannot be inferred from these four dictionaries.
    Unsupported dimensions or unavailable legal placements raise NotImplementedError.
    """
    started = time.monotonic()
    n, k = _arguments(num_qubits, num_excitations)
    args = _clean_calibration(cz_pauli_error_rate, sq_pauli_error_rate, zero_errors, one_errors)
    cz, sq, zero, one = args
    _LAST_SELECTION.clear()
    if len(sq) < n:
        raise NotImplementedError('Insufficient calibrated Willow qubits')
    if k in (0, n):
        errors = zero if k == 0 else one
        outputs = set(sorted(sq, key=lambda q: (rate(errors[q]), q))[:n])
        gate = cirq.PhasedXZGate(x_exponent=int(k == n), z_exponent=0, axis_phase_exponent=0)
        circuit = cirq.Circuit(cirq.Moment(gate(q) for q in sorted(outputs)))
        circuit, outputs = _native_contract(circuit, outputs, n, cz, sq)
        _state_residual(circuit, outputs, n, k)
        return circuit, outputs
    kk = min(k, n - k)
    key = f'{n},{kk}'
    templates = []
    for index, data in enumerate(_MAIN_TEMPLATES.get(key, [])):
        frozen, qubits = _decode_saved(key, index)
        templates.append((cirq.Circuit(frozen), set(qubits), data['source']))
    if not templates:
        # Analytic recurrence retained from FINAL_SUBMISSION_v3 for larger cases.
        circuit = logical_circuit(n, kk)
        circuit = circuit.transform_qubits({q: cirq.GridQubit(0, q.x) for q in circuit.all_qubits()})
        templates.append((circuit, set(circuit.all_qubits()), 'v3_analytic_fallback'))
    choices = []
    fingerprints = set()
    for circuit, outputs, source in templates:
        if time.monotonic() - started > 22:
            break
        if k != kk:
            circuit = circuit + cirq.Circuit(cirq.Moment(
                cirq.PhasedXZGate(x_exponent=1, z_exponent=0, axis_phase_exponent=0)(q)
                for q in sorted(outputs)))
        placements = rank_template(circuit, outputs, k, *args, count=2)
        try:
            original, original_outputs = _native_contract(circuit, outputs, n, cz, sq)
            placements.append((circuit_calibration_cost(original, original_outputs, k, *args),
                               original, original_outputs))
        except NotImplementedError:
            pass
        placements.extend(rank_graph_embeddings(circuit, outputs, k, *args, width=384,
                          count=2, time_budget=min(1.0, max(0.1, 22 - (time.monotonic() - started)))))
        for proxy, candidate, placed in placements:
            fingerprint = cirq.FrozenCircuit(candidate)
            if fingerprint in fingerprints:
                continue
            fingerprints.add(fingerprint)
            try:
                candidate, placed = _native_contract(candidate, placed, n, cz, sq)
            except NotImplementedError:
                continue
            choices.append((proxy, candidate, placed, source))
    if not choices and time.monotonic() - started < 30:
        # Dead couplers may exclude every small patch while leaving a usable path.
        fallback = logical_circuit(n, kk)
        fallback = fallback.transform_qubits({q: cirq.GridQubit(0, q.x) for q in fallback.all_qubits()})
        fallback_outputs = set(fallback.all_qubits())
        if k != kk:
            fallback += cirq.Circuit(cirq.Moment(cirq.PhasedXZGate(
                x_exponent=1, z_exponent=0, axis_phase_exponent=0)(q) for q in sorted(fallback_outputs)))
        for proxy, candidate, placed in rank_graph_embeddings(
                fallback, fallback_outputs, k, *args, width=1024, count=2, time_budget=4.0):
            try:
                candidate, placed = _native_contract(candidate, placed, n, cz, sq)
                choices.append((proxy, candidate, placed, 'v3_analytic_path_fallback'))
            except NotImplementedError:
                continue
    if not choices:
        raise NotImplementedError('No legal placement found on the supplied calibrated graph')
    choices.sort(key=lambda row: (row[0], len(row[1])))
    if n <= 8:
        # Give each source family a finalist before spending budget on alternate placements.
        shortlist, remaining, families = [], [], set()
        for row in choices:
            if row[3] not in families:
                families.add(row[3]); shortlist.append(row)
            else:
                remaining.append(row)
        shortlist = (shortlist + remaining)[:12]
        refined = []
        for row in shortlist:
            if refined and time.monotonic() - started > 38:
                break
            losses = _expected_notebook_losses(row[1], row[2], k, *args)
            if np.all(np.isfinite(losses)):
                refined.append((losses, row))
        if refined:
            lower = np.maximum(np.min([row[0] for row in refined], axis=0), 1e-15)
            refined.sort(key=lambda row: (float(np.max(row[0] / lower)),
                                          float(np.mean(row[0] / lower)), row[1][0]))
            choices = [row[1] for row in refined]
            _LAST_SELECTION['estimated_denominators_all_X_cutoffs'] = refined[0][0].tolist()
    for proxy, circuit, outputs, source in choices:
        if time.monotonic() - started > 48:
            raise NotImplementedError('Construction budget exhausted')
        try:
            residual = _state_residual(circuit, outputs, n, k)
        except NotImplementedError:
            continue
        if time.monotonic() - started >= 58:
            raise NotImplementedError('Construction budget exhausted')
        _LAST_SELECTION.update(source=source, residual=residual, moments=len(circuit),
                               calibrated_proxy=proxy, seconds=time.monotonic() - started)
        return circuit, set(outputs)
    raise NotImplementedError('No candidate passed the exact-state check')


def create_dicke_state_adaptive(num_qubits, num_excitations):
    """Notebook bonus entry point. Organizer-confirmed domain: N=2..15."""
    n, k = _arguments(num_qubits, num_excitations, maximum=15)
    if n < 2 or not 1 <= k <= n // 2:
        raise NotImplementedError('Bonus requires 2<=N<=15 and 1<=k<=N//2')
    return _bonus_selected(n, k)


